add_filter( 'woocommerce_email_recipient_customer_processing_order', 'perfectpixel_free_order_customer_recipient', 99, 2 );
add_filter( 'woocommerce_email_recipient_customer_completed_order', 'perfectpixel_free_order_customer_recipient', 99, 2 );
add_filter( 'woocommerce_email_recipient_new_order', 'perfectpixel_free_order_admin_recipient', 99, 2 );

function perfectpixel_is_free_order( $order ) {
	return $order instanceof WC_Order && 0.0 === (float) $order->get_total();
}

function perfectpixel_free_order_customer_recipient( $recipient, $order ) {
	return ( 'yes' === '{{free_orders_skip_customer}}' && perfectpixel_is_free_order( $order ) ) ? '' : $recipient;
}

function perfectpixel_free_order_admin_recipient( $recipient, $order ) {
	return ( 'yes' === '{{free_orders_skip_admin}}' && perfectpixel_is_free_order( $order ) ) ? '' : $recipient;
}
